from collections import deque
class Solution:
    def findShortestCycle(self, n: int, edges: list[list[int]]) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        best = float('inf')
        for s in range(n):
            dist = [-1] * n
            par = [-1] * n
            dist[s] = 0
            dq = deque([s])
            while dq:
                u = dq.popleft()
                for v in adj[u]:
                    if dist[v] < 0:
                        dist[v] = dist[u] + 1
                        par[v] = u
                        dq.append(v)
                    elif par[u] != v:
                        best = min(best, dist[u] + dist[v] + 1)
        return best if best < float('inf') else -1

