var findShortestCycle = function(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    let best = Infinity;
    for (let s = 0; s < n; s++) {
        const dist = new Array(n).fill(-1), par = new Array(n).fill(-1);
        dist[s] = 0;
        const dq = [s];
        for (let h = 0; h < dq.length; h++) {
            const u = dq[h];
            for (const v of adj[u]) {
                if (dist[v] < 0) { dist[v] = dist[u] + 1; par[v] = u; dq.push(v); }
                else if (par[u] !== v) best = Math.min(best, dist[u] + dist[v] + 1);
            }
        }
    }
    return best === Infinity ? -1 : best;
};
